const { seg, eo, lerp } = kit;

kit.scene('answer-feedback', {
  init(kit) {
    const opts = ['A. POST', 'B. GET', 'C. PATCH', 'D. CONNECT', 'E. None of the above'];
    const optHtml = opts.map((label, i) => {
      return '<div class="af-opt-' + i + '" style="display:flex;align-items:flex-start;gap:12px;padding:10px 12px;border-radius:6px;font-size:18px;line-height:26px">' +
        '<span class="ui-radio af-radio-' + i + '" style="margin-top:4px">' +
          '<span class="ui-radio-dot af-dot-' + i + '" style="opacity:0"></span>' +
        '</span>' +
        '<span style="flex:1;display:flex;flex-direction:column;gap:2px">' +
          '<span class="af-txt-' + i + '">' + label + '</span>' +
          (i === 1 ? '<span class="af-cue-correct" style="display:none;align-items:center;gap:6px;font-size:15px;font-weight:700;color:var(--correct)">' + W.checkSvg() + '<span>Correct</span></span>' : '') +
          (i === 2 ? '<span class="af-cue-wrong" style="display:none;align-items:center;gap:6px;font-size:15px;font-weight:700;color:var(--incorrect)">' + W.crossSvg() + '<span>Your answer</span></span>' : '') +
        '</span>' +
      '</div>';
    }).join('');

    kit.stage.append(kit.h(
      '<div class="ground">' +
      W.studyChrome('4 · Answer Submission & Non-Color Feedback', 'Stable 112x44 action', 'Pending guard · Locked evaluation · Safe retry') +
      '<div class="ui-window" style="left:220px;top:164px;width:940px;height:740px;padding:44px 48px;display:flex;flex-direction:column;gap:18px">' +
        '<div style="font-size:16px;font-weight:600;color:var(--second)">Question 1</div>' +
        '<div style="font-size:21px;line-height:30px;font-weight:600;color:var(--main)">Which HTTP method is defined as safe and idempotent?</div>' +
        '<div style="display:flex;flex-direction:column;gap:6px;margin-top:6px">' + optHtml + '</div>' +
        '<div style="margin-top:12px;position:relative;height:48px;display:flex;align-items:center">' +
          '<div class="af-btn" style="width:112px;height:44px;border-radius:6px;background:var(--disabled-bg);color:var(--second);display:flex;align-items:center;justify-content:center;font-size:15px;font-weight:600">Answer</div>' +
          '<div class="af-result" style="position:absolute;left:0;display:flex;align-items:center;gap:18px;opacity:0">' +
            '<span style="font-size:18px;font-weight:700;color:var(--incorrect)">Incorrect answer</span>' +
            '<span style="font-size:15px;color:var(--second)">Answer locked</span>' +
          '</div>' +
        '</div>' +
      '</div>' +
      '<div style="position:absolute;left:1220px;top:164px;width:540px;display:flex;flex-direction:column;gap:20px">' +
        '<div style="padding:24px;border-radius:12px;background:var(--nav-bg)">' +
          '<div style="font-size:20px;font-weight:700;color:var(--main);margin-bottom:8px">Non-color-only state cues</div>' +
          '<div style="font-size:17px;line-height:25px;color:var(--second)">Radio dot, tint fill, text labels (Correct, Your answer, Incorrect answer, Answer locked), and icons reinforce each state.</div>' +
        '</div>' +
        '<div class="af-retry-card" style="padding:24px;border-radius:12px;background:var(--nav-bg);border:2px solid var(--accent);opacity:0">' +
          '<div style="font-size:20px;font-weight:700;color:var(--main);margin-bottom:8px">Safe retry on uncertain outcome</div>' +
          '<div style="font-size:17px;line-height:25px;color:var(--second);margin-bottom:14px">If submission fails or times out, selection stays intact and Answer allows safe retry without duplicate evaluation.</div>' +
          '<div style="display:flex;align-items:center;gap:14px">' +
            '<div style="width:112px;height:44px;border-radius:6px;background:var(--accent);color:var(--on-brand);display:flex;align-items:center;justify-content:center;font-size:15px;font-weight:600">Answer</div>' +
            '<span style="font-size:15px;font-weight:600;color:var(--main)">Answer not confirmed. Try again.</span>' +
          '</div>' +
        '</div>' +
      '</div>' +
      '</div>'
    ));

    const q = (s) => kit.stage.querySelector(s);
    this.opts = [0, 1, 2, 3, 4].map((i) => ({
      row: q('.af-opt-' + i),
      radio: q('.af-radio-' + i),
      dot: q('.af-dot-' + i),
      txt: q('.af-txt-' + i)
    }));
    this.cueCorrect = q('.af-cue-correct');
    this.cueWrong = q('.af-cue-wrong');
    this.btn = q('.af-btn');
    this.result = q('.af-result');
    this.retryCard = q('.af-retry-card');

    this.cur = kit.cursor();
    this.cur.keys = [
      { t: 0.25, at: [460, 290] },
      { t: 0.8, at: [360, 412] },
      { t: 1.5, at: [324, 622] },
      { t: 2.3, at: [500, 660] }
    ];
    this.cur.clicks = [0.9, 1.6];
    this.cur.visible = (t) => seg(t, 0.15, 0.35) * (1 - seg(t, 2.5, 2.8));
  },
  render(t) {
    const hoverC = seg(t, 0.65, 0.85) * (1 - seg(t, 0.95, 1.05));
    const selectedC = t >= 0.92;
    const pending = t >= 1.65 && t < 2.85;
    const evaluated = t >= 2.85;

    for (let i = 0; i < 5; i++) {
      const o = this.opts[i];
      const isC = i === 2;
      const isB = i === 1;
      if (isC && selectedC) {
        o.row.style.background = 'var(--tint)';
        o.radio.style.borderColor = evaluated ? 'var(--incorrect)' : 'var(--accent)';
        o.dot.style.opacity = 1;
        o.dot.style.background = evaluated ? 'var(--incorrect)' : 'var(--accent)';
      } else if (isC && hoverC > 0.1) {
        o.row.style.background = 'var(--hover-bg)';
        o.radio.style.borderColor = 'var(--second)';
        o.dot.style.opacity = 0;
      } else {
        o.row.style.background = 'transparent';
        o.radio.style.borderColor = 'var(--second)';
        o.dot.style.opacity = 0;
      }
      o.txt.style.color = evaluated && !isB && !isC ? 'var(--second)' : 'var(--main)';
    }

    this.cueCorrect.style.display = evaluated ? 'inline-flex' : 'none';
    this.cueWrong.style.display = evaluated ? 'inline-flex' : 'none';

    if (evaluated) {
      this.btn.style.opacity = 0;
      const resIn = eo(seg(t, 2.85, 3.2));
      this.result.style.opacity = resIn;
      this.result.style.transform = 'translateY(' + lerp(6, 0, resIn).toFixed(1) + 'px)';
    } else if (pending) {
      this.btn.style.opacity = 1;
      this.btn.style.background = 'var(--disabled-bg)';
      this.btn.style.color = 'var(--second)';
      this.btn.textContent = 'Submitting…';
      this.result.style.opacity = 0;
    } else if (selectedC) {
      this.btn.style.opacity = 1;
      this.btn.style.background = 'var(--accent)';
      this.btn.style.color = 'var(--on-brand)';
      this.btn.textContent = 'Answer';
      this.result.style.opacity = 0;
    } else {
      this.btn.style.opacity = 1;
      this.btn.style.background = 'var(--disabled-bg)';
      this.btn.style.color = 'var(--second)';
      this.btn.textContent = 'Answer';
      this.result.style.opacity = 0;
    }

    const retryIn = eo(seg(t, 3.85, 4.3));
    this.retryCard.style.opacity = retryIn;
    this.retryCard.style.transform = 'translateY(' + lerp(12, 0, retryIn).toFixed(1) + 'px)';

    this.cur.render(t);
  }
});
